"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["92397"],{16708(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.municipio_do_fada_referenciado_por_condicao_viva","status":422,"titulo":"Existe condi\xe7\xe3o citando um munic\xedpio que deixaria a \xe1rea do Fator de Atenua\xe7\xe3o das Desigualdades de Acesso (FADA)"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.municipio_do_fada_referenciado_por_condicao_viva","requisitos":[],"oQueAconteceu":["Alguma condi\xe7\xe3o do processo \u2014 regra de item de formul\xe1rio, grupo, deriva\xe7\xe3o de\\nfato, crit\xe9rio de desempate por fato ou exibi\xe7\xe3o condicional \u2014 cita um munic\xedpio\\nque n\xe3o pertence \xe0 \xe1rea do Fator de Atenua\xe7\xe3o das Desigualdades de Acesso (FADA). A \xe1rea \xe9 formada pelos munic\xedpios da\\nbase legal do processo; processo sem o Fator de Atenua\xe7\xe3o das Desigualdades de Acesso (FADA) tem \xe1rea vazia, e qualquer\\nmunic\xedpio citado fica fora dela.","A recusa aparece em dois momentos: ao declarar o Fator de Atenua\xe7\xe3o, quando a\\nnova \xe1rea retiraria um munic\xedpio que a condi\xe7\xe3o ainda cita, e ao congelar uma\\nvers\xe3o (publica\xe7\xe3o ou retifica\xe7\xe3o em ato \xfanico), quando a confer\xeancia final\\nencontra a condi\xe7\xe3o fora da \xe1rea. Em ambos os casos nada \xe9 gravado ou congelado. A mensagem indica o munic\xedpio."],"comoResolver":["Ajuste a condi\xe7\xe3o que cita o munic\xedpio \u2014 removendo-a ou trocando o munic\xedpio\\npor um da \xe1rea \u2014 ou mantenha o munic\xedpio na \xe1rea do Fator de Atenua\xe7\xe3o das Desigualdades de Acesso (FADA) do processo.","Em processo j\xe1 publicado, as altera\xe7\xf5es s\xe3o feitas numa retifica\xe7\xe3o. Depois,\\nrepita a opera\xe7\xe3o recusada."],"ondeAparece":["Declara\xe7\xe3o do Fator de Atenua\xe7\xe3o das Desigualdades de Acesso do processo seletivo","Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3bbcc2307827ee8c6dab135295710bb856847f61"}}')}}]);